def validate_transactions(txns):
    valid, errors = [], []
    for t in txns:
        if 'amount' not in t or 'timestamp' not in t:
            errors.append((t, "Missing required fields"))
        elif t['amount'] <= 0:
            errors.append((t, "Non-positive amount"))
        else:
            valid.append(t)
    return valid, errors

import time
def connect_with_retry(max_attempts=3):
    attempts = 0
    while attempts < max_attempts:
        try:
            # Simulated connection attempt
            if attempts < 2:
                raise ConnectionError("Timeout")
            return "Connected"
        except ConnectionError:
            attempts += 1
            time.sleep(2 ** attempts)
    raise Exception("Max retries reached")

