# Conceptual Python demonstration of an Airflow-style DAG task dependency simulation
class SimpleDAG:
    def __init__(self, dag_id):
        self.dag_id = dag_id
        self.tasks = {}

    def add_task(self, name, func):
        self.tasks[name] = {'func': func, 'downstream': []}

    def set_dependency(self, upstream, downstream):
        self.tasks[upstream]['downstream'].append(downstream)

    def run(self):
        print(f"--- Executing DAG: {self.dag_id} ---")
        for name, task in self.tasks.items():
            print(f"Running Task: {name}")
            task['func']()

# Define tasks
def extract(): print(">> Extracting data from PostgreSQL...")
def transform(): print(">> Transforming data using Pandas/SQL...")
def load(): print(">> Loading data into Snowflake Warehouse...")

# Build Pipeline
pipeline = SimpleDAG("sales_etl_daily")
pipeline.add_task("extract_task", extract)
pipeline.add_task("transform_task", transform)
pipeline.add_task("load_task", load)

pipeline.run()

