def check_dag(graph):
    visited = set()
    def dfs(node):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor)
    graph = {'extract': ['transform'], 'transform': ['load'], 'load': []}
    dfs('extract')
    return len(visited) == len(graph)

